en:
//【護氏】
<voice name='護氏' class='護氏' src='voice/md01/029vs0160a05'>
//「端武者がッ!!」
"Not bad for a whelp!"

pt:
//【護氏】
<voice name='護氏' class='護氏' src='voice/md01/029vs0160a05'>
//「端武者がッ!!」
"Nada mal para um fedelho!"

en:
//【景明】
<voice name='景明' class='景明' src='voice/md01/029vs0170a00'>
//「推参!!」
"By your leave!"

pt:
//【景明】
<voice name='景明' class='景明' src='voice/md01/029vs0170a00'>
//「推参!!」
"Com sua licença!"

en:
//　剣の軌道が交差し、刃金と刃金は弾き合う。
//　
//　が――これは俺の想定の内！
  Our blades cross and are smashed aside, neither scoring so much as a glancing blow.

  As expected!

pt:
//　剣の軌道が交差し、刃金と刃金は弾き合う。
//　
//　が――これは俺の想定の内！
  Nossas lâminas se cruzam e são arremessadas de lado, sem que nenhuma acerte um golpe de raspão.

  Como eu esperava!

en:
//【護氏】
<voice name='護氏' class='護氏' src='voice/md01/029vs0180a05'>
//「む!?」
"Ngh!?"

pt:
//【護氏】
<voice name='護氏' class='護氏' src='voice/md01/029vs0180a05'>
